 5| import { inspect } from 'node:util';
 6| import type { NextFunction, Request, Response } from 'express';
 7| import { z, ZodError } from 'zod';
 8| import { HttpProblem, badRequest, internalError, notFound, typeUri, sendProblem, unprocessable } from './problem.ts';
 9| 
10| /** Shape of the errors thrown by express.json() (body-parser / http-errors). */
11| const BodyParserErrorSchema = z.object({
12|   type: z.string(),
13|   status: z.number().int().min(400).max(499),
14|   message: z.string(),
15| });
16| 
17| /** "email: Invalid email address; name: Too big: expected string to have <=100 characters" */
18| export function formatZodIssues(error: ZodError): string {
19|   return error.issues
20|     .map((issue) => `${issue.path.length > 0 ? issue.path.map(String).join('.') : '(root)'}: ${issue.message}`)
21|     .join('; ');
22| }
23| 
24| export function toHttpProblem(err: unknown): HttpProblem {
25|   if (err instanceof HttpProblem) return err;
26|   if (err instanceof ZodError) return unprocessable(formatZodIssues(err));
27|   const parserError = BodyParserErrorSchema.safeParse(err);
28|   if (parserError.success) {
29|     const { type, status, message } = parserError.data;
30|     if (type === 'entity.parse.failed') return badRequest('The request body is not valid JSON.');
31|     return new HttpProblem({ type: typeUri('request-rejected'), title: 'Request Rejected', status, detail: message });
32|   }
33|   return internalError();
34| }
35| 
36| export function notFoundHandler(req: Request, res: Response): void {
37|   sendProblem(res, notFound(`No route matches ${req.method} ${req.originalUrl}.`).toProblem(req.originalUrl));
38| }
39| 
40| /** Unexpected errors go to stderr for the operator; the client only ever sees the generic 500 problem. */
41| function reportUnexpected(err: unknown): void {
42|   process.stderr.write(`${inspect(err)}\n`);
43| }
44| 
45| export function errorHandler(err: unknown, req: Request, res: Response, next: NextFunction): void {
46|   if (res.headersSent) {
47|     next(err);
48|     return;
49|   }
50|   const problem = toHttpProblem(err);
51|   if (problem.status >= 500) reportUnexpected(err);
52|   sendProblem(res, problem.toProblem(req.originalUrl));
53| }

zod-boundary (standards, unit: handlers)
zod-boundary (unit: route handlers; each hand-written DTO type is one more failing unit)
A route handler passes iff ALL of (its middleware chain counts: validate({ body: S }) and router.use(...) included):
1. Every read of req.params / req.query / req.body / req.headers / req.get() / req.header(), in the handler or a
   middleware, is the direct argument of <schema>.parse() / .safeParse() / .parseAsync() / .safeParseAsync(),
   or follows a middleware that wrote the parsed value back (req.body = S.parse(req.body)). Only serialising a
   whole part with JSON.stringify (to hash it) is exempt. Destructuring or passing `req` along is not.
2. A path with :param segments parses req.params; POST / PUT / PATCH parse req.body (anywhere in the chain).
3. Schemas constrain the data: z.any()/z.unknown()/z.custom() without a type, z.record(k, z.unknown()) and
   z.object({}).passthrough()/.loose() validate nothing and fail, as request or response schemas.
4. Every 2xx (or non-constant status) body sent with res.json(x) / res.send(x) is <schema>.parse(...) (or a const
   / helper returning one) or a full problem. res.status(204).end() is fine. `res` is not passed to helpers
   (problem senders such as sendProblem(res, p) excepted).
Per src file: no hand-written data types: interface, type X = { ... } (also arrays/tuples of them), DTO classes,
or an enum duplicating a z.enum; use type X = z.infer<typeof XSchema>. Method-only interfaces (ports) are fine.
A route whose path cannot be resolved statically and that does not parse req.params is UNPROVEN.
Passing example:
  usersRouter.post('/v1/users', idempotency(), (req, res) => {
    const body = CreateUserSchema.parse(req.body);
    const user = store.create(body);
    res.status(201).location(`/v1/users/${user.id}`).json(UserSchema.parse(user));
  });
  usersRouter.get('/v1/users/:userId', validate({ params: UserParamsSchema }), (req, res) => {
    const user = store.get(req.params.userId);
    if (user === undefined) throw notFound(`user ${req.params.userId} not found`);
    res.json(UserSchema.parse(user));
  });
  export type User = z.infer<typeof UserSchema>;

