  const body = z.object({ email: UserEmailSchema.optional(), name: UserNameSchema.optional(), role: UserRoleSchema.optional() }).superRefine((value, ctx) => {
    if (value.email === undefined && value.name === undefined && value.role === undefined) {
      ctx.addIssue({ code: z.ZodIssueCode.custom, message: 'At least one field must be provided.' });
    }
